	private static String diagnosticRows(SailRepositoryConnection scalarConnection,
			SailRepositoryConnection frontierConnection, String query, String queryKey) {
		String distinctDrugCount = "SELECT (COUNT(DISTINCT ?drug) AS ?count)";
		if (!query.contains(distinctDrugCount)) {
			return "";
		}
		String detailQuery = query.replace(distinctDrugCount,
				"SELECT ?trial ?arm ?drug ?result ?marker ?optMarker ?p ?effect");
		String groupedDrugQuery = query.replace(distinctDrugCount, "SELECT ?drug") + " GROUP BY ?drug";
		return "\nScalar detail rows: " + evaluate(scalarConnection, detailQuery, queryKey + " scalar detail")
				+ "\nFrontier detail rows: "
				+ evaluate(frontierConnection, detailQuery, queryKey + " Frontier detail")
				+ "\nScalar grouped drugs: "
				+ evaluate(scalarConnection, groupedDrugQuery, queryKey + " scalar grouped drugs")
				+ "\nFrontier grouped drugs: "
				+ evaluate(frontierConnection, groupedDrugQuery, queryKey + " Frontier grouped drugs")
				+ "\nFrontier detail plan:\n"
				+ frontierConnection.prepareTupleQuery(detailQuery).explain(Explanation.Level.Optimized).tupleExpr()
				+ "\nFrontier grouped-drug plan:\n"
				+ frontierConnection.prepareTupleQuery(groupedDrugQuery)
						.explain(Explanation.Level.Optimized)
						.tupleExpr()
				+ "\nFrontier aggregate executed plan:\n"
				+ frontierConnection.prepareTupleQuery(query).explain(Explanation.Level.Executed).tupleExpr();
	}

	private static ResultBag evaluate(SailRepositoryConnection connection, String queryString, String queryKey) {
		Map<ResultRow, Long> rows = new HashMap<>();
		var query = connection.prepareTupleQuery(queryString);
		query.setMaxExecutionTime(QUERY_REGRESSION_TIMEOUT_SECONDS);
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.merge(ResultRow.from(result.next()), 1L, Long::sum);
			}
		} catch (RuntimeException | Error failure) {
			throw new AssertionError(queryKey + " did not complete on bounded coverage data", failure);
		}
		return new ResultBag(Map.copyOf(rows));
	}

	private static List<Theme> selectedThemes() {
		String configured = System.getProperty(THEMES_PROPERTY);
		if (configured == null || configured.isBlank()) {
			return List.of(Theme.values());
		}
		return Arrays.stream(configured.split(","))
				.map(String::trim)
				.filter(value -> !value.isEmpty())
				.map(Theme::valueOf)
				.toList();
	}

	private static List<Integer> selectedQueryIndexes() {
		String configured = System.getProperty(QUERY_INDEXES_PROPERTY);
		if (configured == null || configured.isBlank()) {
			List<Integer> indexes = new ArrayList<>(ThemeQueryCatalog.QUERY_COUNT);
			for (int index = 0; index < ThemeQueryCatalog.QUERY_COUNT; index++) {
				indexes.add(index);
			}
			return List.copyOf(indexes);
		}
		return Arrays.stream(configured.split(","))
				.map(String::trim)
				.filter(value -> !value.isEmpty())
				.map(Integer::valueOf)
				.peek(index -> {
					if (index < 0 || index >= ThemeQueryCatalog.QUERY_COUNT) {
						throw new IllegalArgumentException("Query index out of range: " + index);
					}
				})
				.toList();
	}

	private static void auditFrontierCoverage(Theme theme, int queryIndex, TupleExpr expression,
			List<String> coverageFailures) {
		int failureCount = coverageFailures.size();
		FrontierClassification classification = classify(expression, coverageFailures,
				theme.name() + " q" + queryIndex);
		if (classification.supported == 0 && classification.degraded == 0) {
			coverageFailures.add(theme + " q" + queryIndex
					+ " published neither theorem-safe Frontier evidence nor an explicit fallback\n" + expression);
		} else if (coverageFailures.size() != failureCount) {
			coverageFailures.add(theme + " q" + queryIndex + " optimized plan:\n" + expression);
		}
	}

	private static FrontierClassification classify(TupleExpr expression, List<String> coverageFailures,
			String queryKey) {
		FrontierClassification classification = new FrontierClassification();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr) {
					classifyNode(node, classification, coverageFailures, queryKey);
				}
				node.visitChildren(this);
			}
		});
		return classification;
	}

	private static void classifyNode(QueryModelNode node, FrontierClassification classification,
			List<String> coverageFailures, String queryKey) {
		String status = node.getStringMetricPlanned("plannedFrontierStatus");
		if (status == null) {
			return;
		}
		QueryModelNode parent = node.getParentNode();
		String nodeKey = queryKey + " " + node.getClass().getSimpleName()
				+ "[source=" + node.getStringMetricPlanned("plannedEstimateSource")
				+ ", parent=" + (parent == null ? "none" : parent.getClass().getSimpleName())
				+ ", state=" + node.getDoubleMetricPlanned("plannedFrontierStateId")
				+ ", factors=" + node.getDoubleMetricPlanned("plannedFrontierFactorCount")
				+ ", guarantee=" + node.getStringMetricPlanned("plannedFrontierGuarantee")
				+ childStateSummary(node) + "]";
		switch (status) {
		case "ready":
			classification.supported++;
			String guarantee = node.getStringMetricPlanned("plannedFrontierGuarantee");
			if (guarantee == null || guarantee.isBlank() || "unresolved".equals(guarantee)) {
				coverageFailures.add(nodeKey + " is ready without a theorem-safe guarantee");
			}
			if (node.getDoubleMetricPlanned("plannedFrontierStateId") <= 0.0d) {
				coverageFailures.add(nodeKey + " is ready without a query-local evidence state");
			}
			break;
		case "degraded":
		case "disabled_zero_budget":
		case "dirty_insertion":
		case "dirty_deletion":
		case "missing":
		case "corrupt":
		case "truncated":
		case "version_mismatch":
		case "store_mismatch":
		case "epoch_mismatch":
		case "schema_mismatch":
		case "hash_mismatch":
		case "budget_exceeded":
		case "snapshot_mismatch":
		case "unavailable":
			classification.degraded++;
			String fallbackReason = node.getStringMetricPlanned("plannedFrontierFallbackReason");
			if (fallbackReason == null || fallbackReason.isBlank()) {
				coverageFailures.add(nodeKey + " is " + status + " without a stable fallback reason");
			}
			break;
		default:
			coverageFailures.add(nodeKey + " has unrecognized Frontier status " + status);
			break;
		}
	}

	private static String childStateSummary(QueryModelNode node) {
		if (!(node instanceof BinaryTupleOperator binary)) {
			return "";
		}
		return ", children="
				+ binary.getLeftArg().getClass().getSimpleName() + ":"
				+ binary.getLeftArg().getDoubleMetricPlanned("plannedFrontierStateId") + "+"
				+ binary.getRightArg().getClass().getSimpleName() + ":"
				+ binary.getRightArg().getDoubleMetricPlanned("plannedFrontierStateId");
	}

	private static final class FrontierClassification {

		private int supported;
		private int degraded;
	}

	private record ResultBag(Map<ResultRow, Long> rows) {
	}

	private record ResultRow(List<String> names, List<Value> values) {

		private static ResultRow from(BindingSet bindings) {
			List<String> names = bindings.getBindingNames().stream().sorted().toList();
			return new ResultRow(names, names.stream().map(bindings::getValue).toList());
		}
	}
